function auQuizHL(d){const bs=[...V.querySelectorAll('.choices button[data-c]')];if(!bs.length)return false;let i=bs.findIndex(b=>b.classList.contains('hl'));
  bs.forEach(b=>b.classList.remove('hl'));i=i<0?(d>0?0:bs.length-1):Math.min(bs.length-1,Math.max(0,i+d));bs[i].classList.add('hl');bs[i].scrollIntoView({block:'nearest'});AU.hlc=bs[i].dataset.c;return true}
function auQuizOK(){const h=V.querySelector('.choices button.hl[data-c]');if(h&&!V.querySelector('.choices button.ok,.choices button.no')){h.click();return true}return clickId('qn')||clickId('qs')||clickId('qf')}
/* 스와이프 방향 → 리모컨 버튼 자리. 링의 '왼쪽' 버튼은 손가락을 오른쪽으로 미는 신호를 보내요(책장 앞으로 넘김). 반대면 설정에서 바꿔요. */
function auSlotOfSwipe(dir){const o=AU.opt||{};if(dir==='r'||dir==='l'){let left=dir==='r';if(o.swapLR)left=!left;return left?'gl':'gr'}let up=dir==='u';if(o.swapUD)up=!up;return up?'gu':'gd'}
