async function pull(){for(let t=0;t<40&&(typeof db==='undefined'||!db);t++)await new Promise(r=>setTimeout(r,500));if(typeof db==='undefined'||!db)return;
  try{const sn=await db.collection('data/users/'+uid).doc('journal').get();if(!sn.exists)return;const R=(sn.data()||{}).days||{};let ch=false;
    for(const k in R){const a=LJ.d[k],b=R[k];if(!a){LJ.d[k]=b;ch=true;continue}if((b.sec||0)>(a.sec||0)){LJ.d[k]=Object.assign({},b,{seq:(b.seq||[]).length>=(a.seq||[]).length?b.seq:a.seq});ch=true}}
    if(ch){try{localStorage.setItem(K,JSON.stringify({v:1,days:LJ.d}))}catch(e){}if(cur==='journal')journalView()}}catch(e){}}
/* 기록 시작 전 날짜: 문제별 마지막 풀이 기록으로 대략 채우기 */
function backfill(){if(localStorage.getItem('reb_journal_bf'))return;const by={};
  for(const id in P){const r=P[id],q=BYID[id];if(!q||!r[4])continue;const d=new Date(r[4]),k=ds(d);if(LJ.d[k])continue;const x=by[k]||(by[k]={sec:0,lsec:0,q:0,ok:0,s:{},ox:0,oxs:{},ex:0,ses:[],seq:[],approx:true});
    x.q++;if(r[1]===1)x.ok++;const ss=x.s[q.s]||(x.s[q.s]=[0,0]);ss[0]++;if(r[1]===1)ss[1]++;x.seq.push([mins(d),q.s,r[1]===1?1:r[1]===0?0:-1])}
  Object.assign(LJ.d,by);try{localStorage.setItem('reb_journal_bf','1')}catch(e){}save()}
/* ---- 기록 훅 ---- */
